    new StockItem("NEG", -1, 0, 10),
    new StockItem("SKIP", 20, 0, 10),
    new StockItem("D", 1, 0, 1)
};

var planner = new ReplenishmentPlanner();
var plan = planner.BuildPlan(items, supplier, 4);

Check.NotNull(plan);
Check.SequenceEqual(new[] { "A:15", "B:LARGE:300", "C:FAILED" }, plan);
